class Solution:
    def maximumTotalSum(self, maximumHeight: List[int]) -> int:
        maximumHeight.sort(reverse=True)
        prev = float('inf')
        total = 0
        for cap in maximumHeight:
            h = min(cap, prev - 1)
            if h < 1:
                return -1
            total += h
            prev = h
        return total

