class Solution {
public:
    long long maximumTotalSum(vector<int>& maximumHeight) {
        sort(maximumHeight.rbegin(), maximumHeight.rend());
        long long prev = LLONG_MAX, total = 0;
        for (int cap : maximumHeight) {
            long long h = min((long long)cap, prev - 1);
            if (h < 1) return -1;
            total += h;
            prev = h;
        }
        return total;
    }
};

