class Solution {
    public long maximumTotalSum(int[] maximumHeight) {
        Arrays.sort(maximumHeight);
        long prev = Long.MAX_VALUE, total = 0;
        for (int i = maximumHeight.length - 1; i >= 0; i--) {
            long h = Math.min((long) maximumHeight[i], prev - 1);
            if (h < 1) return -1;
            total += h;
            prev = h;
        }
        return total;
    }
}

