var maximumTotalSum = function(maximumHeight) {
    maximumHeight.sort((a, b) => b - a);
    let prev = Infinity, total = 0;
    for (const cap of maximumHeight) {
        const h = Math.min(cap, prev - 1);
        if (h < 1) return -1;
        total += h;
        prev = h;
    }
    return total;
};
